internal fun additionalPokemonCardArtworkOverrides(): List<PokemonCardArtworkOverride> = buildList {
    addAll(additionalArtworkChunk0())
    addAll(additionalArtworkChunk1())
    addAll(additionalArtworkChunk2())
    addAll(additionalArtworkChunk3())
    addAll(additionalArtworkChunk4())
    addAll(additionalArtworkChunk5())
    addAll(additionalArtworkChunk6())
    addAll(additionalArtworkChunk7())
    addAll(additionalArtworkChunk8())
    addAll(additionalArtworkChunk9())
    addAll(additionalArtworkChunk10())
    addAll(additionalArtworkChunk11())
}

private fun parseAdditionalArtwork(rows: String): List<PokemonCardArtworkOverride> =
    rows.trimIndent().lineSequence().filter(String::isNotBlank).map { row ->
        val fields = row.split('|')
        require(fields.size == 5)
        PokemonCardArtworkOverride(
            sourceSetId = fields[0], sourceCardId = fields[1], sourceLocalId = fields[2],
            replacement = PokemonCardArtwork(fields[3], fields[4]),
        )
    }.toList()

